# demo py
import streamlit as st
import pandas as pd
import plotly.express as px
from analyze import analyze
from html import escape
from base64 import b64encode

# ========页面标题=========
st.set_page_config(page_title="校园诉求小帮手", page_icon=":school:", layout="wide", initial_sidebar_state="expanded")
st.markdown(
    """
    <style>
    .stApp { background: #ff7770; color: #111; }
    header[data-testid="stHeader"] { background: transparent; }
    /* The outer Streamlit block is only a layout host; the keyed panel owns its background. */
    .stMainBlockContainer { width: 80vw !important; max-width: 80vw !important;
        padding: 0 !important; margin: clamp(20px, 4vh, 36px) auto !important; height: auto !important; }
    [data-testid="stSidebar"] { background: #ff7770; border: none;
        width: 17vw !important; min-width: 17vw !important; max-width: 17vw !important;
        transform: none !important; position: relative !important; }
    [data-testid="stSidebarHeader"], [data-testid="stSidebarCollapseButton"],
    [data-testid="stExpandSidebarButton"] { display: none; }
    [data-testid="stSidebarContent"] { padding-top: clamp(20px, 4vh, 36px); }
    [data-testid="stSidebarUserContent"] { padding: clamp(12px, 1.6vw, 28px); }
    [data-testid="stSidebar"] h1 { color: #fff !important; font-size: clamp(24px, 3vw, 44px); }
    /* Target the widget's labels at any nesting depth: Streamlit wraps radio options. */
    [data-testid="stSidebar"] [data-testid="stRadio"] { padding-top: clamp(16px, 5vh, 48px); }
    [data-testid="stSidebar"] [data-testid="stRadio"] [role="radiogroup"] { gap: 0; }
    [data-testid="stSidebar"] [data-testid="stRadio"] label {
        margin: clamp(12px, 4vh, 40px) 0 !important; padding: 12px 8px;
        border-radius: 12px; min-height: 44px; width: 100%; box-sizing: border-box; }
    [data-testid="stSidebar"] [data-testid="stRadio"] label,
    [data-testid="stSidebar"] [data-testid="stRadio"] label p,
    [data-testid="stSidebar"] [data-testid="stRadio"] label span {
        color: #fff !important; font-size: clamp(16px, 1.9vw, 28px) !important;
        font-weight: 700 !important; white-space: nowrap; }
    [data-testid="stSidebar"] [data-testid="stRadio"] label:has(input:checked) { background: #ffffff25; }
    [data-testid="stSidebar"] [data-testid="stRadio"] label:hover { background: #ffffff18; }
    .st-key-content_panel { position: relative; box-sizing: border-box; width: 100%;
        height: auto !important; min-height: calc(100vh - 72px); padding: 24px clamp(14px, 2.5vw, 40px) 36px;
        background: #f5f5f5; border: 1px solid #d5d5d5; border-radius: 20px; }
    .st-key-content_panel [data-testid="stVerticalBlock"] { height: auto; }
    .st-key-content_panel [data-testid="stColumn"] { min-width: 0; }
    .st-key-content_panel [data-testid="stPlotlyChart"] { background: transparent; }
    h1, h2, h3, p, [data-testid="stMetricValue"], [data-testid="stMetricLabel"] { color: #111; }
    [data-testid="stTextArea"] textarea { background: #ffe3e2; color: #111; border-radius: 16px; padding: 22px; }
    [data-testid="stTextArea"] [data-baseweb="textarea"] { background: #ffe3e2; border: none; border-radius: 16px; }
    button[kind="primary"] { background: #ff777d; color: #111; border: none; border-radius: 15px; min-height: 44px; }
    button[kind="primary"]:hover { background: #f46067; color: #111; }
    .result-card { background: white; border: 1px solid #dedede; border-radius: 18px; padding: 28px 16px;
        min-height: 195px; text-align: center; box-shadow: 0 3px 8px #0000000a; }
    .result-icon { display: inline-flex; align-items: center; justify-content: center; width: 52px; height: 52px;
        border-radius: 50%; font-size: 26px; margin-bottom: 12px; }
    .result-label { color: #777; font-size: 14px; margin-bottom: 10px; }
    .result-value { color: #111; font-size: 22px; font-weight: 700; overflow-wrap: anywhere; }
    .school-mark { display: flex; justify-content: flex-end; height: 56px; width: 100%; }
    .school-mark img { display: block; width: 56px; height: 56px; object-fit: contain; }
    .history-wrap { height: 420px; max-height: 60vh; overflow: auto; padding: 0 8px 8px;
        border: 1px solid #dedede; border-radius: 12px; background: transparent; }
    .history-wrap table.history-table { width: 100%; min-width: 520px; border-collapse: separate !important;
        border-spacing: 0 10px !important; color: #111; border: 0 !important; table-layout: fixed; }
    .history-wrap .history-table th { position: sticky; top: 0; z-index: 1; background: #f5f5f5;
        text-align: left; padding: 12px; font-weight: 500; border: 0; }
    .history-wrap .history-table th:first-child { width: 48%; }
    .history-wrap .history-table td { background: #ffffffa6; padding: 14px 12px; border: 0 !important;
        overflow-wrap: anywhere; transition: background .18s; }
    .history-wrap .history-table td:first-child { border-radius: 10px 0 0 10px; }
    .history-wrap .history-table td:last-child { border-radius: 0 10px 10px 0; }
    .history-wrap .history-table tbody tr:hover td { background: #ffac94; }
    .urgency-tag { border-radius: 6px; padding: 4px 12px; white-space: nowrap; color: #111; background: #ffe5b5; }
    .urgency-high { background: #ffc5bd; } .urgency-low { background: #d9ecdf; }
    .feedback-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 250px), 1fr));
        gap: clamp(16px, 2vw, 32px); margin: 24px 0; width: 100%; }
    .feedback-card { box-sizing: border-box; min-width: 0; background: white;
        border-radius: 18px; padding: clamp(18px, 2vw, 30px); }
    .feedback-card p { font-size: clamp(16px, 1.3vw, 20px); line-height: 1.8; }
    .feedback-labels { display: flex; flex-wrap: wrap; gap: 16px; margin-top: 40px; }
    .feedback-labels span { background: #ffe3dc; border: 2px solid #e76e51; border-radius: 14px;
        padding: 5px 18px; white-space: nowrap; }
    .feedback-emails { background: #ff7400; display: flex; flex-direction: column; justify-content: space-around; gap: 24px; }
    .feedback-emails p { color: white; margin: 0; font-size: clamp(14px, 1.2vw, 18px); overflow-wrap: anywhere; }
    @media(max-width: 640px) {
        .st-key-content_panel [data-testid="stHorizontalBlock"] { flex-wrap: wrap; }
        .st-key-content_panel [data-testid="stColumn"] { flex: 1 1 100% !important; width: 100% !important; }
    }
    @media(max-height: 500px) {
        [data-testid="stSidebarContent"] { padding-top: 0; }
        [data-testid="stSidebar"] [data-testid="stRadio"] { padding-top: 0; }
        [data-testid="stSidebar"] [data-testid="stRadio"] label { margin: 6px 0 !important; padding: 8px 4px; }
    }
    </style>
    """,
    unsafe_allow_html=True,
)
with st.sidebar:
    st.title("MENU")
    page = st.radio("页面导航", ["学生", "管理员", "意见反馈"], label_visibility="collapsed")
# Embed the supplied image so the single-file app does not depend on a temporary path.
SCHOOL_LOGO = "data:image/jpeg;base64,"


# ------------ 学生端
def show_result_card(icon, title, value, background, color):
    safe_value = escape(str(value))

    st.markdown(
        f"""
        <div class="result-card">
            <div class="result-icon"
                 style="background-color: {background}; color: {color};">
                {icon}
            </div>
            <div class="result-label">{title}</div>
            <div class="result-value">{safe_value}</div>
        </div>
        """,
        unsafe_allow_html=True,
    )


# One real Streamlit container owns every page element, including charts and feedback.
with st.container(key="content_panel"):
    # Render a self-contained SVG as an image. Inline SVG filter/image tags can
    # be stripped by the HTML sanitizer, leaving an invisible placeholder.
    logo_svg = f"""<svg xmlns="http://www.w3.org/2000/svg" viewBox="10 605 875 875" width="56" height="56">
      <defs><filter id="logo-alpha" color-interpolation-filters="sRGB">
        <feColorMatrix type="matrix" values="0 0 0 0 .67  0 0 0 0 0  0 0 0 0 .16  0 -1 0 0 1"/>
      </filter></defs>
      <image href="{SCHOOL_LOGO}" width="943" height="2048" filter="url(#logo-alpha)"/>
    </svg>"""
    logo_uri = "data:image/svg+xml;base64," + b64encode(logo_svg.encode("utf-8")).decode("ascii")
    st.markdown(
        f'<div class="school-mark"><img src="{logo_uri}" alt="中国人民大学校徽" width="56" height="56"></div>',
        unsafe_allow_html=True,
    )

    if page == "学生":
        with st.container(border=False):
            st.subheader("提交你的诉求")

            content = st.text_area(
                "诉求内容",
                placeholder="例如：宿舍洗衣机坏了三天，希望尽快维修。",
                max_chars=200,
                height=220,
                label_visibility="collapsed",
            )

            submit_btn = st.button(
                "提交并分析",
                type="primary",
                width="stretch",
            )
        if submit_btn:
            if not content.strip():
                st.warning("请输入诉求内容后再提交。")
            else:
                try:
                    result = analyze(content)
                    summary = result["summary"]
                    label = result["label"]
                    urgency = result["urgency"]
                    department = result["department"]

                    urgency_colors = {
                        "低": ("#E8F7EE", "#15803D"),
                        "中": ("#FFF4D6", "#B7791F"),
                        "高": ("#FEECEC", "#DC2626"),
                    }

                    urgency_background, urgency_color = urgency_colors.get(
                        urgency,
                        ("#EEF2F7", "#64748B"),
                    )

                    col_summary, col_category, col_urgency, col_department = st.columns(4)

                    with col_summary:
                        show_result_card(
                            "🍣",
                            "摘要",
                            summary,
                            "#E8F0FF",
                            "#EB2546",
                        )

                    with col_category:
                        show_result_card(
                            "🏠",
                            "类别",
                            label,
                            "#E8F0FF",
                            "#2563EB",
                        )

                    with col_urgency:
                        show_result_card(
                            "!",
                            "紧急度",
                            urgency,
                            urgency_background,
                            urgency_color,
                        )

                    with col_department:
                        show_result_card(
                            "👥",
                            "负责部门",
                            department,
                            "#E8F7EE",
                            "#15803D",
                        )
                    if result["error"] is not None:
                        st.error(f"错误：{result['error']}")

                    # 追加写入csv
                    new_row = pd.DataFrame({"summary": [summary], "label": [label], "urgency": [urgency], "department": [department]})
                    new_row.to_csv("data/history.csv", mode="a", header=False, index=False, encoding="utf-8-sig")

                except Exception as e:
                    st.error(f"❌ 分析失败: {e}")

    # ------------ 管理员端
    elif page == "管理员":
        st.header("管理端首页 - 诉求统计数据面板")
        st.divider()

        # 读取csv,增加异常保护,防止空文件报错崩溃
        try:
            df = pd.read_csv("data/history.csv")
            st.success("✅ 数据加载成功")
        except (pd.errors.EmptyDataError, FileNotFoundError):
            st.warning("history.csv文件为空!")
            df = pd.DataFrame(columns=["content", "label", "urgency", "department"])

        # 基础指标
        total_count = len(df)
        high_urgency_count = len(df[df["urgency"] == "高"])
        col1, col2 = st.columns(2)
        with col1:
            st.metric(label="总诉求数量", value=total_count)
        with col2:
            st.metric(label="高紧急度诉求数量", value=high_urgency_count)

        st.divider()

        # 两张可视化图表
        if not df.empty:
            chart_left, chart_right = st.columns(2)
            palette = ["#ef553b", "#ff8e7f", "#ffb479", "#ffd373", "#f7a5a0", "#d66a50"]
            cat_count = df["label"].value_counts().reset_index()
            fig1 = px.bar(cat_count, x="label", y="count", title="各类诉求数量", color="label", color_discrete_sequence=palette)
            urg_count = df["urgency"].value_counts().reset_index()
            fig2 = px.pie(
                urg_count,
                names="urgency",
                values="count",
                title="紧急程度分布",
                color="urgency",
                color_discrete_map={"高": "#ef553b", "中": "#ffac72", "低": "#ffd373"},
            )
            for figure in (fig1, fig2):
                figure.update_layout(
                    paper_bgcolor="rgba(0,0,0,0)", plot_bgcolor="rgba(0,0,0,0)", font_color="#111111", height=360, margin=dict(l=20, r=20, t=50, b=30)
                )
            fig1.update_layout(showlegend=False)
            with chart_left:
                st.plotly_chart(fig1, width="stretch", theme=None)
            with chart_right:
                st.plotly_chart(fig2, width="stretch", theme=None)

            st.divider()
            st.subheader("原始诉求数据表")
            # HTML table supports whole-row hover while escaping all stored user content.
            headers = "".join(f"<th>{escape(str(col))}</th>" for col in df.columns)
            rows = []
            for values in df.itertuples(index=False, name=None):
                cells = []
                for column, value in zip(df.columns, values):
                    text = escape(str(value))
                    if column == "urgency":
                        tag = {"高": "urgency-high", "低": "urgency-low"}.get(str(value), "")
                        text = f'<span class="urgency-tag {tag}">{text}</span>'
                    cells.append(f"<td>{text}</td>")
                rows.append("<tr>" + "".join(cells) + "</tr>")
            st.markdown(
                '<div class="history-wrap"><table class="history-table"><thead><tr>'
                + headers
                + "</tr></thead><tbody>"
                + "".join(rows)
                + "</tbody></table></div>",
                unsafe_allow_html=True,
            )

        else:
            st.info("暂无诉求数据,提交诉求后图标会自动生成")

    elif page == "意见反馈":
        # Static display only: no links, navigation, or submission actions.
        st.markdown(
            """
        <div class="feedback-grid">
          <div class="feedback-card">
            <p>以下是我们的意见反馈邮箱<br>遇到任何使用上的问题<br>可以选取任意一个邮箱反馈给我们<br>您是否满意我们的服务?</p>
            <div class="feedback-labels"><span>满意</span><span>很满意</span><span>非常满意</span></div>
          </div>
          <div class="feedback-card feedback-emails">
            <p>2026202830@ruc.edu.cn</p><p>2026202831@ruc.edu.cn</p>
            <p>2026202832@ruc.edu.cn</p><p>2026202834@ruc.edu.cn</p>
          </div>
        </div>
        """,
            unsafe_allow_html=True,
        )
